examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchStepper(
        steps = listOf(
            MonarchStepperStep(id = {{steps.0.id}}, label = {{steps.0.label}}),
            MonarchStepperStep(id = {{steps.1.id}}, label = {{steps.1.label}}),
            MonarchStepperStep(id = {{steps.2.id}}, label = {{steps.2.label}}, optional = {{steps.2.optional}}),
            MonarchStepperStep(id = {{steps.3.id}}, label = {{steps.3.label}}),
        ),
        current = current,
        furthest = furthest,
        onSelect = { _, index ->
            current = index
            furthest = maxOf(furthest, index)
        },
    )
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchButton(
            text = {{back}},
            onClick = { current -= 1 },
            variant = MonarchButtonVariant.Secondary,
            enabled = current != 0,
        )
        MonarchButton(
            text = {{continue}},
            onClick = {
                current += 1
                furthest = maxOf(furthest, current)
            },
            variant = MonarchButtonVariant.Primary,
            enabled = current != 3,
        )
    }
}

